package dev.mineagent.runtime.agent.body;
import dev.mineagent.runtime.api.agent.BodyDomain;import org.junit.jupiter.api.Test;import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.jupiter.api.Assertions.*;
class BodyControlCoordinatorTest {
 @Test void higherPriorityCancelsChildButKeepsSessionDecisionWithCaller(){var c=new BodyControlCoordinator();var farm=UUID.randomUUID();var fight=UUID.randomUUID();var op=UUID.randomUUID();var canceled=new AtomicInteger();var interrupted=new AtomicInteger();assertTrue(c.acquire(farm,Set.of(BodyDomain.MOVEMENT),10,()->true,interrupted::incrementAndGet));assertTrue(c.claimChild(farm,op,()->true,canceled::incrementAndGet));assertTrue(c.acquire(fight,Set.of(BodyDomain.MOVEMENT),100,()->true,()->{}));assertEquals(1,canceled.get());assertEquals(1,interrupted.get());assertFalse(c.claimChild(farm,UUID.randomUUID(),()->true,()->fail()));c.release(fight);assertTrue(c.acquire(farm,Set.of(BodyDomain.MOVEMENT),10,()->true,()->{}));}
 @Test void staleChildCannotReleaseNewParent(){var c=new BodyControlCoordinator();var a=UUID.randomUUID();var b=UUID.randomUUID();var op=UUID.randomUUID();c.acquire(a,Set.of(BodyDomain.MAIN_HAND),10,()->true,()->{});c.claimChild(a,op,()->true,()->{});c.acquire(b,Set.of(BodyDomain.MAIN_HAND),20,()->true,()->{});c.releaseChild(op);c.release(a);assertTrue(c.owns(b,BodyDomain.MAIN_HAND));}
}
